# Hanan grid DP for terminal set, using Dreyfus-Wagner
rows=[3,6,8,10,12]; cols=[1,4,6,8,10,12]
pts=[(3,6),(6,4),(8,1),(8,12),(10,10),(12,8)]
verts=[(r,c) for r in rows for c in cols]; n=len(pts); N=len(verts)
idx={v:i for i,v in enumerate(verts)}
adj=[[] for _ in verts]
for r in rows:
 for j in range(len(cols)-1):
  a=idx[(r,cols[j])];b=idx[(r,cols[j+1])];w=cols[j+1]-cols[j]
  adj[a].append((b,w));adj[b].append((a,w))
for c in cols:
 for j in range(len(rows)-1):
  a=idx[(rows[j],c)];b=idx[(rows[j+1],c)];w=rows[j+1]-rows[j]
  adj[a].append((b,w));adj[b].append((a,w))
import heapq, math
INF=10**9; dp={}; par={}
# for each subset, merge at every vertex, then shortest path closure
for i,p in enumerate(pts):
 s=1<<i; ds=[INF]*N; ds[idx[p]]=0; pp=[None]*N
 # shortest distance init one-terminal
 h=[(0,idx[p])]
 while h:
  d,v=heapq.heappop(h)
  if d!=ds[v]: continue
  for u,w in adj[v]:
   if ds[u]>d+w: ds[u]=d+w; pp[u]=('edge',v);heapq.heappush(h,(ds[u],u))
 dp[s]=ds;par[s]=pp
for size in range(2,n+1):
 for mask in range(1,1<<n):
  if mask.bit_count()!=size: continue
  ds=[INF]*N; pp=[None]*N
  sub=(mask-1)&mask
  while sub:
   other=mask^sub
   if other and sub<other:
    a=dp[sub];b=dp[other]
    for v in range(N):
     val=a[v]+b[v]
     if val<ds[v]: ds[v]=val;pp[v]=('merge',sub,other,v)
   sub=(sub-1)&mask
  h=[(d,v) for v,d in enumerate(ds) if d<INF];heapq.heapify(h)
  while h:
   d,v=heapq.heappop(h)
   if d!=ds[v]:continue
   for u,w in adj[v]:
    if ds[u]>d+w: ds[u]=d+w;pp[u]=('edge',v);heapq.heappush(h,(ds[u],u))
  dp[mask]=ds;par[mask]=pp
full=(1<<n)-1; mincost=min(dp[full]);mincost, [(verts[v],d) for v,d in enumerate(dp[full]) if d==mincost][:10]

